import{_ as l,o as r,c as i,a2 as e}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"裸机云 VNC 控制台使用指南","description":"","frontmatter":{"title":"裸机云 VNC 控制台使用指南"},"headers":[],"relativePath":"ops-knowledge-base/baremetal/vnc-console-guide.md","filePath":"ops-knowledge-base/baremetal/vnc-console-guide.md","lastUpdated":1794309341000}'),o={name:"ops-knowledge-base/baremetal/vnc-console-guide.md"};function t(n,a,s,h,p,d){return r(),i("div",null,[...a[0]||(a[0]=[e('<h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>本文档介绍如何通过裸机云控制台使用 VNC（Virtual Network Computing）远程连接服务器，以及 VNC 的常见使用场景和相关功能说明。</p><p><strong>适用产品：</strong> 裸机云（Bare Metal Cloud）</p><hr><h2 id="一、什么是-vnc-控制台" tabindex="-1">一、什么是 VNC 控制台？ <a class="header-anchor" href="#一、什么是-vnc-控制台" aria-label="Permalink to &quot;一、什么是 VNC 控制台？&quot;">​</a></h2><p>VNC（Virtual Network Computing）是一种服务器控制台连接方式，可直接访问服务器的图形控制台。</p><p>与 SSH 或远程桌面（RDP）不同，VNC 不依赖服务器的网络服务，即使 SSH 或 RDP 无法连接，也通常可以通过 VNC 登录服务器进行管理。</p><hr><h2 id="二、什么时候建议使用-vnc" tabindex="-1">二、什么时候建议使用 VNC？ <a class="header-anchor" href="#二、什么时候建议使用-vnc" aria-label="Permalink to &quot;二、什么时候建议使用 VNC？&quot;">​</a></h2><p>建议在以下场景使用 VNC：</p><ul><li>SSH 无法连接（Linux）</li><li>远程桌面（RDP）无法连接（Windows）</li><li>忘记服务器登录密码</li><li>修改服务器网络配置</li><li>查看服务器启动过程</li><li>系统无法正常启动</li><li>系统维护或故障排查</li></ul><hr><h2 id="三、如何打开-vnc-控制台" tabindex="-1">三、如何打开 VNC 控制台？ <a class="header-anchor" href="#三、如何打开-vnc-控制台" aria-label="Permalink to &quot;三、如何打开 VNC 控制台？&quot;">​</a></h2><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><ol><li>登录 Raksmart 客户后台。</li><li>进入 <strong>产品管理</strong> → <strong>裸机云</strong>。</li><li>选择需要管理的服务器。</li><li>点击进入 <strong>管理</strong> 页面。</li><li>点击 <strong>VNC</strong> 按钮。</li><li>系统将自动打开一个新的浏览器页面，并建立 VNC 控制台连接。</li><li>连接成功后，即可在控制台窗口中看到服务器当前画面。</li><li>使用服务器的系统账号和密码登录即可。</li></ol><blockquote><p><strong>说明：</strong></p><p>VNC 登录使用的是服务器操作系统的账号和密码（例如 Linux 的 <strong>root</strong> 或 Windows 的 <strong>Administrator</strong>），并非 Raksmart 后台账号。</p></blockquote><hr><h2 id="四、vnc-控制台功能介绍" tabindex="-1">四、VNC 控制台功能介绍 <a class="header-anchor" href="#四、vnc-控制台功能介绍" aria-label="Permalink to &quot;四、VNC 控制台功能介绍&quot;">​</a></h2><p>VNC 页面右上角提供了以下常用功能：</p><h3 id="密码粘贴-paste-password" tabindex="-1">密码粘贴（Paste Password） <a class="header-anchor" href="#密码粘贴-paste-password" aria-label="Permalink to &quot;密码粘贴（Paste Password）&quot;">​</a></h3><p>可将复制好的密码快速粘贴到服务器登录界面。</p><p>适用于：</p><ul><li>登录密码较长或包含特殊字符；</li><li>避免手动输入密码时出现错误。</li></ul><hr><h3 id="剪切板-clipboard" tabindex="-1">剪切板（Clipboard） <a class="header-anchor" href="#剪切板-clipboard" aria-label="Permalink to &quot;剪切板（Clipboard）&quot;">​</a></h3><p>用于在本地电脑与 VNC 控制台之间复制和粘贴文本内容。</p><p>适用于：</p><ul><li>复制命令到服务器；</li><li>复制服务器中的文本内容；</li><li>提高操作效率。</li></ul><blockquote><p><strong>说明：</strong></p><p>剪切板主要用于文本内容的复制，不支持文件传输。</p></blockquote><hr><h3 id="发送-ctrl-alt-del" tabindex="-1">发送 Ctrl + Alt + Del <a class="header-anchor" href="#发送-ctrl-alt-del" aria-label="Permalink to &quot;发送 Ctrl + Alt + Del&quot;">​</a></h3><p>向服务器发送 <strong>Ctrl + Alt + Del</strong> 组合键。</p><p>适用于：</p><ul><li>Windows 登录界面；</li><li>打开 Windows 安全选项；</li><li>解锁 Windows 会话；</li><li>登录需要按 <strong>Ctrl + Alt + Del</strong> 的 Windows 系统。</li></ul><hr><h2 id="五、vnc-可以执行哪些操作" tabindex="-1">五、VNC 可以执行哪些操作？ <a class="header-anchor" href="#五、vnc-可以执行哪些操作" aria-label="Permalink to &quot;五、VNC 可以执行哪些操作？&quot;">​</a></h2><p>通过 VNC 可以完成服务器的大部分日常管理操作，例如：</p><ul><li>登录服务器系统</li><li>修改系统密码</li><li>查看服务器启动状态</li><li>修改网络配置</li><li>重启服务器</li><li>检查系统异常</li><li>系统维护及故障排查</li></ul><p>对于 Linux 系统，还可以：</p><ul><li>进入单用户模式</li><li>修复系统配置</li><li>查看启动日志</li></ul><hr><h2 id="六、常见问题" tabindex="-1">六、常见问题 <a class="header-anchor" href="#六、常见问题" aria-label="Permalink to &quot;六、常见问题&quot;">​</a></h2><h3 id="q1-vnc-登录使用什么账号和密码" tabindex="-1">Q1：VNC 登录使用什么账号和密码？ <a class="header-anchor" href="#q1-vnc-登录使用什么账号和密码" aria-label="Permalink to &quot;Q1：VNC 登录使用什么账号和密码？&quot;">​</a></h3><p>VNC 使用的是服务器操作系统的账号和密码。</p><p>例如：</p><p>Linux 默认使用 <strong>root</strong> 用户。</p><p>Windows 默认使用 <strong>Administrator</strong> 用户。</p><hr><h3 id="q2-为什么-ssh-或-rdp-无法连接-但-vnc-可以登录" tabindex="-1">Q2：为什么 SSH 或 RDP 无法连接，但 VNC 可以登录？ <a class="header-anchor" href="#q2-为什么-ssh-或-rdp-无法连接-但-vnc-可以登录" aria-label="Permalink to &quot;Q2：为什么 SSH 或 RDP 无法连接，但 VNC 可以登录？&quot;">​</a></h3><p>SSH 和 RDP 依赖服务器网络及相关服务正常运行。</p><p>VNC 直接连接服务器控制台，因此即使网络配置异常或远程服务未启动，通常仍可通过 VNC 登录服务器。</p><hr><h3 id="q3-vnc-可以修改服务器密码吗" tabindex="-1">Q3：VNC 可以修改服务器密码吗？ <a class="header-anchor" href="#q3-vnc-可以修改服务器密码吗" aria-label="Permalink to &quot;Q3：VNC 可以修改服务器密码吗？&quot;">​</a></h3><p>可以。</p><p>登录系统后，可按照操作系统的方式修改密码。</p><p>如果忘记服务器密码，也可以使用控制台中的 <strong>重置密码</strong> 功能重新设置密码。</p><p>详细操作请参考：《<a href="/ops-knowledge-base/baremetal/password-change-reset-guide.html">裸机云密码修改与重置指南</a>》。</p><hr><h3 id="q4-vnc-可以复制文件吗" tabindex="-1">Q4：VNC 可以复制文件吗？ <a class="header-anchor" href="#q4-vnc-可以复制文件吗" aria-label="Permalink to &quot;Q4：VNC 可以复制文件吗？&quot;">​</a></h3><p>不可以。</p><p>VNC 控制台提供的 <strong>剪切板（Clipboard）</strong> 功能主要用于复制和粘贴文本内容，不支持直接传输文件。</p><p>如需传输文件，建议使用：</p><ul><li>Linux：SCP、SFTP 等方式；</li><li>Windows：远程桌面共享、FTP 或其他文件传输工具。</li></ul><hr><h3 id="q5-关闭浏览器页面会影响服务器运行吗" tabindex="-1">Q5：关闭浏览器页面会影响服务器运行吗？ <a class="header-anchor" href="#q5-关闭浏览器页面会影响服务器运行吗" aria-label="Permalink to &quot;Q5：关闭浏览器页面会影响服务器运行吗？&quot;">​</a></h3><p>不会。</p><p>关闭 VNC 页面仅断开当前控制台连接，不会影响服务器的正常运行。</p><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>⚠️ VNC 登录使用的是服务器系统账号，而不是 Raksmart 客户后台账号。</p><p>⚠️ VNC 可作为 SSH 或 RDP 无法连接时的应急管理方式，但日常管理仍建议优先使用 SSH（Linux）或远程桌面（Windows）。</p><p>⚠️ 剪切板功能仅支持文本复制，不支持文件传输。</p><p>⚠️ 如需修改系统配置或执行高风险操作，建议提前做好数据备份。</p><hr>',74)])])}const C=l(o,[["render",t]]);export{u as __pageData,C as default};
